import{_ as e,c as l,o as t,b0 as o}from"./chunks/framework.Becqh7-x.js";const m=JSON.parse('{"title":"LV010-V4L2简介","description":null,"frontmatter":{"title":"LV010-V4L2简介","date":"2026-03-25T19:58:36.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/application/camera/126d397c803c379eaa963af0","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-25T19:58:36.889Z","fulluuid":"eaa963af01dd48489f6a2350ff9e0a0d","useduuid":"eaa963af0"}},"headers":[],"relativePath":"sdoc/application/camera/126d397c803c379eaa963af0.md","filePath":"sdoc/20-应用开发/27-摄像头应用/LV010-V4L2简介.md","lastUpdated":1774449904000}'),r={name:"sdoc/application/camera/126d397c803c379eaa963af0.md"};function i(n,a,d,c,p,s){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="lv010-v4l2简介" tabindex="-1">LV010-V4L2简介 <a class="header-anchor" href="#lv010-v4l2简介" aria-label="Permalink to &quot;LV010-V4L2简介&quot;">​</a></h1><h2 id="一、v4l2-简介" tabindex="-1">一、V4l2 简介 <a class="header-anchor" href="#一、v4l2-简介" aria-label="Permalink to &quot;一、V4l2 简介&quot;">​</a></h2><p>V4L2(Video for Linux 2)：Linux 内核中中的一个标准化的视频设备驱动框架，对上向应用层提供统一的接口，对下支持各类复杂硬件的灵活扩展。应用于控制各类视频设备，如 USB 摄像头，MIPI 摄像头，TV 收音机，HDMI 输入/输出等。</p><p>它提供了一套经过定义的 API，使用户态端应用程序可以通过 <code>/dev/videoX</code> 设备节点，以方式操作文件调用来读取或控制视频设备。</p><h2 id="二、简单示例" tabindex="-1">二、简单示例 <a class="header-anchor" href="#二、简单示例" aria-label="Permalink to &quot;二、简单示例&quot;">​</a></h2><p>直接看这两个示例：<a href="https://gitee.com/linux-dev-org/imx6ull-app-demo/tree/main/LV30_Camera" target="_blank" rel="noreferrer">imx6ull-app-demo: i.mx6ull应用开发学习demo - Gitee.com</a></p><p>这里仅仅是简单了解下V4L2怎么使用，具体其实内部很多含义都还不是很清楚，后续会在RK3568开发板上从摄像头驱动开始到V4L2采集整个流程的学习。</p><blockquote><p>参考资料：</p><p><a href="https://linuxkernel.org.cn/doc/html/latest/driver-api/media/v4l2-core.html" target="_blank" rel="noreferrer">2. Video4Linux 设备 — Linux 内核文档 - Linux 内核</a></p></blockquote>',8)])])}const f=e(r,[["render",i]]);export{m as __pageData,f as default};
